# Función para buscar la sección SAS anterior

def encontrar_seccion_4233(indice_linea):

    secciones = [
        "INPUT",
        "INFORMAT",
        "FORMAT",
        "LABEL"
    ]

    for indice in range(indice_linea, -1, -1):

        linea = (
            lineas_4233[indice]
            .strip()
            .upper()
        )

        for seccion in secciones:

            if linea.startswith(seccion):
                return seccion

    return "SECCIÓN NO IDENTIFICADA"


